internal val gameSearchIconsByPath = gameSearchIcons.associateBy { it.path }
internal fun taskIconIsMonochrome(path: String): Boolean = if (taskIconSymbol(path) != null) true else gameSearchIconsByPath[path]?.monochrome
    ?: (path in setOf("filter_icons/legendary.png", "filter_icons/mythical.png", "filter_icons/costume.png", "filter_icons/favorite_empty.png"))
